// hypbr atlas: Basalt Lava Cobble (basalt_lava_cobble) | 1 tile = 1.4 m x 1.4 m
import * as THREE from 'three';
const SURFACE_W = 7, SURFACE_H = 20; // meters covered by the mesh UV 0..1
const base = 'https://hypbr.vercel.app/assets/mats/basalt_lava_cobble/';
const loader = new THREE.TextureLoader().setCrossOrigin('anonymous');
function tex(file, srgb) {
  const t = loader.load(base + file);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(SURFACE_W / 1.4, SURFACE_H / 1.4);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = 8;
  return t;
}
const orm = tex('orm.webp', false); // R=AO, G=Roughness, B=Metallic
const material = new THREE.MeshPhysicalMaterial({
  map: tex('albedo_delit.webp', true),
  normalMap: tex('normal.webp', false), // OpenGL +Y = three.js native
  aoMap: orm, roughnessMap: orm, metalnessMap: orm,
  roughness: 1.0, metalness: 1.0,
  displacementMap: tex('aux.webp', false), displacementScale: 0.03, displacementBias: -0.015, // aux.R height; dense mesh only
  ior: 1.5,
});
mesh.material = material;
